    const contentKey = byContent ? `${runwayOrigin ? 'runway:' + runwayWorldOriginId(runwayOrigin) : preview.contentFingerprint(worldSnapshot)}|${
      preview.contentFingerprint(unit)}|${hostileSide}|${windowCount}` : '';
